messages.content:
Tool response:
Tool: find_available_campsites
Description: Search for campsites that can accommodate a specific RV size and party size 
within the given dates, optionally filtering by amenities/hookups.

A campsite is considered available if there are no overlapping confirmed/pending reservations
for the requested dates.
Parameters:
    {
      "type": "object",
      "properties": {
        "check_in_date": {
          "type": "string",
          "description": "Check-in date in YYYY-MM-DD format",
          "title": "Check In Date"
        },
        "check_out_date": {
          "type": "string",
          "description": "Check-out date in YYYY-MM-DD format",
          "title": "Check Out Date"
        },
        "max_rv_length": {
          "type": "integer",
          "description": "Maximum RV length in feet (e.g., 40)",
          "title": "Max Rv Length"
        },
        "max_occupancy": {
          "type": "integer",
          "description": "Maximum occupancy (e.g., 5)",
          "title": "Max Occupancy"
        },
        "has_electric_30_amp": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter for sites with 30 amp electric hookups",
          "title": "Has Electric 30 Amp"
        },
        "has_electric_50_amp": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter for sites with 50 amp electric hookups",
          "title": "Has Electric 50 Amp"
        },
        "has_water": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter for sites with water hookups",
          "title": "Has Water"
        },
        "has_sewer": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter for sites with sewer hookups",
          "title": "Has Sewer"
        },
        "has_full_hookups": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter for sites with full hookups (electric, water, sewer)",
          "title": "Has Full Hookups"
        }
      },
      "required": [
        "check_in_date",
        "check_out_date",
        "max_rv_length",
        "max_occupancy"
      ]
    }
